from django import forms
from .models import Product, Category


class ProductForm(forms.ModelForm):
    class Meta:
        # Tell Django which model this form is based on
        model = Product


        # List only the fields you want the user to fill in
        # 'id', created_at, etc. are excluded because they are automatically generated by Django
        fields = ['name', 'description', 'price', 'stock', 'category', 'image']


        # Optional: customize widgets (HTML input elements) for specific fields
        widgets = {
            'name': forms.TextInput(
                attrs={'placeholder': 'Product name'}
            ),
            'price': forms.NumberInput(
                attrs={'min': '0'}
            ),
        }

class CategoryForm(forms.ModelForm):
    class Meta:
        model = Category

        # '__all__' includes every field on the model
        fields = '__all__'